import threading, time

lock_a, lock_b = threading.Lock(), threading.Lock()
got = {}

def philosopher_1():
    with lock_a:                                   # takes A first
        time.sleep(0.1)                            # lets the other grab B
        got["t1 wants B"] = lock_b.acquire(timeout=0.5)
        if got["t1 wants B"]:
            lock_b.release()

def philosopher_2():
    with lock_b:                                   # takes B first - opposite order!
        time.sleep(0.1)
        got["t2 wants A"] = lock_a.acquire(timeout=0.5)
        if got["t2 wants A"]:
            lock_a.release()

threads = [threading.Thread(target=f, daemon=True) for f in (philosopher_1, philosopher_2)]
for t in threads:
    t.start()
for t in threads:
    t.join(timeout=5)

print(f"t1 got B: {got.get('t1 wants B')}   t2 got A: {got.get('t2 wants A')}")
if not got.get("t1 wants B") and not got.get("t2 wants A"):
    print("potential deadlock detected: each holds one lock and waits on the other (circular wait)")
    print("without the acquire timeouts, this cell would hang forever")
